set -euo pipefail
cd /home/ubuntu/apps/travel-planner
echo  | base64 -d > rag/eval/run_routing_challenge.py
echo  | base64 -d > rag/eval/cases/routing_challenge_v1.jsonl
echo  | base64 -d > rag/eval/cases/routing_challenge_v1.manifest.json
export PYTHONPATH=rag
export HF_HUB_OFFLINE=1
.venv/bin/python rag/eval/run_routing_challenge.py --cases rag/eval/cases/routing_challenge_v1.jsonl --output rag/eval/reports/routing_challenge_v1_run1.json --freeze rag/eval/baselines/routing_v2_frozen 2> /tmp/travel-challenge-stderr.log
